<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE)session_start();
$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
if(empty($_SESSION['user'])){header('Location:index.php');exit;}
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
require_once $root.'/app/Core/ProjectFollowup.php';require_once $root.'/app/Core/UnifiedSidebar.php';ensureProjectFollowupSchema($db);
$action=(string)($_GET['a']??'project_followup');$projectId=(int)($_GET['id']??$_POST['project_id']??0);
if(in_array($action,['quote_followup','save_quote_followup'],true)){$quoteId=(int)($_GET['id']??$_POST['quote_id']??0);$q=$db->prepare('SELECT project_id FROM quotes WHERE id=?');$q->execute([$quoteId]);$projectId=(int)$q->fetchColumn();if($action==='quote_followup'&&$projectId){header('Location:?a=project_followup&id='.$projectId);exit;}}
if($action==='save_project_followup'||$action==='save_quote_followup'){
    if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??''))){http_response_code(419);exit('Solicitud vencida.');}
    $event=(string)($_POST['event_type']??'nota');$allowed=['cliente_contactado','reprogramado','nota','cerrado','reabierto'];if(!in_array($event,$allowed,true))$event='nota';
    $notes=trim((string)($_POST['notes']??''));$next=trim((string)($_POST['next_contact_date']??''));$next=$next!==''?$next:null;$userId=(int)($_SESSION['user']['id']??0);
    if($event==='cliente_contactado'&&!$next)$next=projectFollowupBusinessDate(date('Y-m-d'));
    $db->beginTransaction();
    if($event==='cerrado')$db->prepare('UPDATE projects SET next_followup_date=NULL,followup_closed_at=NOW(),followup_reminder_sent_at=NULL WHERE id=?')->execute([$projectId]);
    else $db->prepare('UPDATE projects SET followup_responsible_user_id=?,next_followup_date=?,followup_closed_at=NULL,followup_reminder_sent_at=NULL WHERE id=?')->execute([$userId?:null,$next,$projectId]);
    $db->prepare('INSERT INTO project_followup_history(project_id,user_id,event_type,next_contact_date,notes) VALUES(?,?,?,?,?)')->execute([$projectId,$userId?:null,$event,$next,$notes!==''?$notes:null]);$db->commit();
    $_SESSION['msg']='Seguimiento del proyecto actualizado.';header('Location:?a=project_followup&id='.$projectId);exit;
}
$s=$db->prepare('SELECT p.*,c.business_name,c.contact_name,c.email,c.phone,u.name responsible_name FROM projects p JOIN clients c ON c.id=p.client_id LEFT JOIN users u ON u.id=p.followup_responsible_user_id WHERE p.id=?');$s->execute([$projectId]);$project=$s->fetch();if(!$project){http_response_code(404);exit('Proyecto inexistente.');}
$s=$db->prepare('SELECT id,proposal_name,version_no,status,quote_date,sent_at,total,currency FROM quotes WHERE project_id=? ORDER BY quote_date DESC,id DESC');$s->execute([$projectId]);$quotes=$s->fetchAll();
$s=$db->prepare('SELECT h.*,u.name user_name,q.proposal_name,q.version_no FROM project_followup_history h LEFT JOIN users u ON u.id=h.user_id LEFT JOIN quotes q ON q.id=h.source_quote_id WHERE h.project_id=? ORDER BY h.event_date DESC,h.id DESC');$s->execute([$projectId]);$history=$s->fetchAll();
if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));$msg=$_SESSION['msg']??null;unset($_SESSION['msg']);$e=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$phone=preg_replace('/\D+/','',(string)$project['phone']);$text='Hola '.($project['contact_name']?:$project['business_name']).', te contacto por el proyecto '.$project['project_number'].' · '.$project['name'].'.';
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seguimiento del proyecto · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}.main{margin-left:var(--sidebar);padding:32px 4%}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.c7{grid-column:span 7}.c5{grid-column:span 5}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:8px;padding:9px 13px;background:var(--o);color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.btn.light{background:#edf0f3;color:var(--ink)}.muted{color:var(--muted)}label{display:block;font-weight:700;margin:12px 0 6px}input,select,textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--line);border-radius:8px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid var(--line)}.flash{padding:12px;background:#eef8f1;border:1px solid #b9dfc5;border-radius:9px;margin-bottom:16px}@media(max-width:900px){.main{margin-left:0;padding:22px 18px}.c7,.c5{grid-column:span 12}}</style></head><body><?php erpSidebar('projects');?><main class="main"><?php if($msg):?><div class="flash"><?=$e($msg)?></div><?php endif;?><div class="actions"><div style="flex:1"><span class="muted">Seguimiento comercial por proyecto</span><h1><?=$e($project['project_number'].' · '.$project['name'])?></h1><p class="muted"><?=$e($project['business_name'])?> · Responsable: <?=$e($project['responsible_name']?:'Sin asignar')?></p></div><a class="btn light" href="?a=project&id=<?=$projectId?>">Volver al proyecto</a><a class="btn light" href="?a=followup_agenda">Agenda</a></div><div class="grid"><section class="card c7"><h2>Próximo contacto</h2><?php if($project['followup_closed_at']):?><p><b>Seguimiento cerrado</b> el <?=date('d/m/Y',strtotime($project['followup_closed_at']))?></p><?php elseif($project['next_followup_date']):?><p>Programado para <b><?=date('d/m/Y',strtotime($project['next_followup_date']))?></b></p><?php else:?><p class="muted">Todavía no hay un contacto programado.</p><?php endif;?><form method="post" action="?a=save_project_followup"><input type="hidden" name="csrf" value="<?=$e($_SESSION['csrf'])?>"><input type="hidden" name="project_id" value="<?=$projectId?>"><label>Acción</label><select name="event_type"><option value="cliente_contactado">Cliente contactado</option><option value="reprogramado">Reprogramar contacto</option><option value="nota">Agregar nota</option><?php if($project['followup_closed_at']):?><option value="reabierto">Reabrir seguimiento</option><?php else:?><option value="cerrado">Cerrar seguimiento</option><?php endif;?></select><label>Próxima fecha</label><input type="date" name="next_contact_date" value="<?=$e($project['next_followup_date'])?>"><label>Notas</label><textarea name="notes" rows="4"></textarea><div class="actions" style="margin-top:14px"><button class="btn" type="submit">Guardar seguimiento</button><?php if($phone):?><a class="btn light" target="_blank" href="https://wa.me/<?=$e($phone)?>?text=<?=rawurlencode($text)?>">WhatsApp</a><?php endif;?><?php if($project['email']):?><a class="btn light" href="mailto:<?=$e($project['email'])?>?subject=<?=rawurlencode('Seguimiento del proyecto '.$project['project_number'])?>&body=<?=rawurlencode($text)?>">Email</a><?php endif;?></div></form></section><section class="card c5"><h2>Presupuestos del proyecto</h2><?php foreach($quotes as $q):?><p><a href="?a=quote_view&id=<?=(int)$q['id']?>"><b><?=$e(trim((string)$q['proposal_name'])?:'Presupuesto')?> · v<?=$e($q['version_no'])?></b></a><br><span class="muted"><?=$e($q['status'])?> · <?=date('d/m/Y',strtotime($q['quote_date']))?></span></p><?php endforeach;?><?php if(!$quotes):?><p class="muted">Sin presupuestos.</p><?php endif;?></section></div><section class="card"><h2>Historial del proyecto</h2><table><tr><th>Fecha</th><th>Acción</th><th>Presupuesto de origen</th><th>Próximo contacto</th><th>Notas</th><th>Usuario</th></tr><?php foreach($history as $h):?><tr><td><?=date('d/m/Y H:i',strtotime($h['event_date']))?></td><td><?=$e(str_replace('_',' ',$h['event_type']))?></td><td><?=$h['source_quote_id']?$e((trim((string)$h['proposal_name'])?:'Presupuesto').' · v'.$h['version_no']):'—'?></td><td><?=$h['next_contact_date']?date('d/m/Y',strtotime($h['next_contact_date'])):'—'?></td><td><?=$e($h['notes'])?></td><td><?=$e($h['user_name']?:'Sistema')?></td></tr><?php endforeach;?><?php if(!$history):?><tr><td colspan="6" class="muted">Todavía no hay movimientos.</td></tr><?php endif;?></table></section></main></body></html>
